# your-service-name — adaptable service template (see wiki/getting-started.md)
"""Autogenerated migrations render the UTCDateTime type as a plain, importable one."""

from __future__ import annotations

from typing import Any

import sqlalchemy as sa
from alembic.autogenerate import render_python_code
from alembic.operations import ops
from sqlalchemy import Column, MetaData, Table

from your_service_name.backend.db.migrations_render import render_item
from your_service_name.backend.db.models import UTCDateTime


def test_utc_datetime_renders_as_a_plain_timezone_aware_datetime() -> None:
    column: Column[Any] = Column("seen_at", UTCDateTime(), nullable=True)
    Table("t", MetaData(), column)
    assert render_item("type", column.type, None) == "sa.DateTime(timezone=True)"


def test_other_types_use_the_default_rendering() -> None:
    assert render_item("type", sa.String(), None) is False
    assert render_item("column", object(), None) is False


def test_a_generated_add_column_does_not_mention_the_custom_type() -> None:
    op = ops.AddColumnOp("t", Column("seen_at", UTCDateTime(), nullable=True))
    code = render_python_code(ops.UpgradeOps(ops=[op]), render_item=render_item)
    assert "UTCDateTime" not in code
    assert "sa.DateTime(timezone=True)" in code
